package org.apache.commons.lang3.time;

import java.io.*;
import java.math.*;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.GregorianCalendar;
import java.util.Iterator;
import java.util.NoSuchElementException;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class DateUtils_isSameLocalTime_TriageGen1Test {

    @Test
    public void testIsSameLocalTime_NullFirstArgument_ThrowsException() {
        try {
            DateUtils.isSameLocalTime(null, Calendar.getInstance());
            Assert.fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            Assert.assertEquals("The date must not be null", e.getMessage());
        }
    }

    @Test
    public void testIsSameLocalTime_NullSecondArgument_ThrowsException() {
        try {
            DateUtils.isSameLocalTime(Calendar.getInstance(), null);
            Assert.fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            Assert.assertEquals("The date must not be null", e.getMessage());
        }
    }

    @Test
    public void testIsSameLocalTime_IdenticalCalendars_ReturnsTrue() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        // Ensure they are exactly the same
        cal2.setTimeInMillis(cal1.getTimeInMillis());

        Assert.assertTrue(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentYear_ReturnsFalse() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        cal1.set(Calendar.YEAR, 2020);
        cal2.set(Calendar.YEAR, 2021);

        Assert.assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentEra_ReturnsFalse() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        cal1.set(Calendar.ERA, Calendar.BC);
        cal2.set(Calendar.ERA, Calendar.AD);

        Assert.assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentDayOfYear_ReturnsFalse() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        cal1.set(Calendar.DAY_OF_YEAR, 100);
        cal2.set(Calendar.DAY_OF_YEAR, 101);

        Assert.assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentHour_ReturnsFalse() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        cal1.set(Calendar.HOUR, 10);
        cal2.set(Calendar.HOUR, 11);

        Assert.assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentMinute_ReturnsFalse() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        cal1.set(Calendar.MINUTE, 30);
        cal2.set(Calendar.MINUTE, 31);

        Assert.assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentSecond_ReturnsFalse() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        cal1.set(Calendar.SECOND, 15);
        cal2.set(Calendar.SECOND, 16);

        Assert.assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentMillisecond_ReturnsFalse() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        cal1.set(Calendar.MILLISECOND, 500);
        cal2.set(Calendar.MILLISECOND, 501);

        Assert.assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentClass_ReturnsFalse() {
        // Using GregorianCalendar vs a custom subclass or different implementation if possible
        // Since Calendar.getInstance() usually returns GregorianCalendar, 
        // we can mock or create a subclass to test the cal1.getClass() == cal2.getClass() branch.
        class CustomCalendar extends GregorianCalendar {}

        Calendar cal1 = new CustomCalendar();
        Calendar cal2 = new GregorianCalendar();

        // Set fields to match to isolate the class check
        int year = 2023;
        int month = 5;
        int day = 10;
        int hour = 12;
        int min = 30;
        int sec = 0;
        int ms = 0;

        cal1.set(year, month, day, hour, min, sec);
        cal1.set(Calendar.MILLISECOND, ms);
        cal1.set(Calendar.ERA, Calendar.AD);

        cal2.set(year, month, day, hour, min, sec);
        cal2.set(Calendar.MILLISECOND, ms);
        cal2.set(Calendar.ERA, Calendar.AD);

        Assert.assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }
}
